.single .wp-block-image img {
	display: block;
	margin: 0 auto;
}



/* h2 css */

.single .entry-content h2 {
	  font-size: 1.3em;
    margin: 1.15em 0 0.6em 0;
    font-weight: 600;
    position: relative;
    text-shadow: 0 -1px rgba(0,0,0,0.6);
    line-height: 40px;
    background: linear-gradient(to right,#2780bb 50%,#2a2a72);
    border: 1px solid #fff;
    padding: 5px 15px;
    color: white;
    border-radius: 5px 5px 5px 5px;
    box-shadow: inset 0 0 5px rgba(53,86,129, 0.5);
    font-family: 'Muli', sans-serif;

}

/* h3 css */

.single .entry-content h3 {
margin: 1em 0 0.65em 0;
    font-weight: 600;
    font-family: 'Titillium Web', sans-serif;
    position: relative;
    text-shadow: 0 -1px 1px rgba(0,0,0,0.4);
    font-size: 22px;
    line-height: 40px;
    color: #355681;
    text-transform: uppercase;
    border-bottom: 1px solid rgba(53,86,129, 0.3);



}

.gb-block-image {
	display:block;
	overflow:hidden;
}
.gb-block-image img{
	transition:0.3s;
}

.gb-block-image img:hover{
	transform:scale(1.1);
}

.gb-container:before,
.gb-container:before{
transition:0.3s;
}

.gb-container:hover:before,
.gb-container:hover:before{
transform:scale(1.1);
}
